sql.where:
l.biz = #{biz} and l.type = #{type}
and l.cfgid = #{cfgId}



            and l.cfgid in
            #{cid}

        and 1 = 0


and l.op = #{op}
and l.batch_id = #{batchId}

    and (l.oa_title like #{keywordLike} or l.oa_sub_name like #{keywordLike}
         or l.oa_dept_name like #{keywordLike} or l.oa_id like #{keywordLike})


    and (l.modedatacreatedate > #{fromDate}
         or (l.modedatacreatedate = #{fromDate} and l.modedatacreatetime >= #{fromTime}))


    and (l.modedatacreatedate < #{toDate}
         or (l.modedatacreatedate = #{toDate} and l.modedatacreatetime <= #{toTime}))

mapper.select:
select top 1 l.op from ${mtgSyncLogTable} l
where l.biz = #{biz} and l.type = #{type} and l.cfgid = #{cfgId} and l.oa_id = #{oaId}
order by l.id desc

select distinct cast(l.oa_id as varchar(64)) from ${mtgSyncLogTable} l
where l.biz = #{biz} and l.type = #{type} and l.cfgid = #{cfgId}
  and l.oa_id in
  #{oid}

select top 1  from ${mtgSyncLogTable} l
where l.biz = #{biz} and l.type = #{type} and l.cfgid = #{cfgId} and l.oa_id = #{oaId}
order by l.id desc

select top ${limit}
    , c.corp_name as cfg_name,
    (select count(1) from ${mtgSyncLogTable} x
      where x.biz = l.biz and x.type = l.type and x.cfgid = l.cfgid and x.oa_id = l.oa_id) as try_count
from ${mtgSyncLogTable} l
left join ${cfgTable} c on c.id = l.cfgid
where l.biz = #{biz} and l.type = #{type}
  and l.id = (select max(x2.id) from ${mtgSyncLogTable} x2
               where x2.biz = l.biz and x2.type = l.type and x2.cfgid = l.cfgid and x2.oa_id = l.oa_id)
  and l.cfgid = #{cfgId}



              and l.cfgid in
              #{cid}

          and 1 = 0


  and l.op = #{op}

      and (l.oa_title like #{keywordLike} or l.oa_sub_name like #{keywordLike} or l.oa_id like #{keywordLike})

order by l.modedatacreatedate desc, l.modedatacreatetime desc, l.id desc

