mapper.select:
select top ${limit} u.id, u.biz, u.type, u.cfgid, u.oa_user_id, u.enabled, u.dir_mode, u.dir_oa2third, u.dir_third2oa, u.remark, u.modedatamodifydatetime, c.corp_name as cfg_name, h.lastname as oa_user_name, h.loginid as oa_user_loginid, h.subcompanyid1 as oa_sub_id, s.subcompanyname as oa_sub_name, h.departmentid as oa_dept_id, d.departmentname as oa_dept_name from ${mtgSyncUserTable} u left join ${cfgTable} c on c.id = u.cfgid left join hrmresource h on h.id = u.oa_user_id left join hrmdepartment d on d.id = h.departmentid left join hrmsubcompany s on s.id = h.subcompanyid1
u.biz = #{biz} and u.type = #{type} and u.dir_mode = 1 and u.cfgid = #{cfgId}
and u.cfgid in #{cid}
and 1 = 0
and h.subcompanyid1 in #{sid}
and h.departmentid in #{did}
and u.dir_oa2third = 1 and u.dir_third2oa = 0 and u.dir_oa2third = 0 and u.dir_third2oa = 1 and u.dir_oa2third = 1 and u.dir_third2oa = 1
and (h.lastname like #{keywordLike} or h.loginid like #{keywordLike})
order by u.modedatamodifydatetime desc, u.id desc

